let budgetSample={day:3,weekly:38,short:12,overdrive:false,subscription:''},accountSample={day:1,hour:12,used:38};
try{const saved=JSON.parse(sessionStorage.getItem('conductor-budget-sample')||'null');if(saved&&Number.isFinite(saved.day)&&saved.day>=0&&saved.day<=7)budgetSample={...budgetSample,...saved};}catch{}
function sampleHourLabel(value){const m=Math.round(+value*60);return Math.floor(m/60)+'h '+String(m%60).padStart(2,'0')+'m of 5h';}
function policyBar(d,time){return `<div class="powerbar" role="img" aria-label="${esc(time)}, ${fmt(d.used)} percent used, ${esc(d.band)} sample" style="background:linear-gradient(to right,var(--green) 0 ${d.green_end}%,var(--orange) ${d.green_end}% ${d.red_start}%,var(--red) ${d.red_start}% 100%)"><span class="marker sample-${d.band}" style="left:${d.used}%"></span></div><p class="hint">${esc(time)} · ${fmt(d.used)}% used · ${fmt(100-d.used)}% remaining</p><p class="sample-state ${d.band}">Current sample: ${esc(d.band)}</p>`;}
function sampleDayLabel(value){const whole=Math.floor(+value),hours=Math.round((+value-whole)*24*10)/10;return whole+' '+(whole===1?'day':'days')+(hours?' + '+hours+' hrs':'')+' of 7 days';}
function testerHeading(title){return `<div class="toolbar"><h3>${title}</h3><span class="badge">Sample · no live changes</span></div>`;}
function loadPolicyTester(){const el=$('#policy-tester');if(!el)return;budgetSample.hour??=0;const range=(label,name,value,max,step)=>`<div><label for="${name}">${label}</label><input id="${name}" type="range" min="0" max="${max}" step="${step}" name="sample.${name}" value="${value}"></div>`;el.innerHTML=testerHeading('Try the power bands')+`<div class="grid">${range('Sample day · '+sampleDayLabel(budgetSample.day),'budgetDay',budgetSample.day,7,1/24)}${range('Weekly used · '+budgetSample.weekly+'%','budgetWeekly',budgetSample.weekly,100,1)}</div><div id="policy-weekly-bar"></div><div class="grid">${range('Elapsed · '+sampleHourLabel(budgetSample.hour),'budgetHour',budgetSample.hour,5,1/60)}${range('Five-hour used · '+budgetSample.short+'%','budgetShort',budgetSample.short,100,1)}</div><div id="policy-short-bar"></div><div id="policy-results" role="status"></div>`;evaluateBudget();}
let policySerial=0;
async function evaluateBudget(){if(dialogState?.type!=='power_bands')return;const current=dialogState,serial=++policySerial;$('#policy-results').textContent='Updating sample…';try{capture($('#definition-form'),current.item);const policy=copy(current.item);policy.name||='Draft power band';const d=await api('policy-preview',{policy,day:+budgetSample.day,hour:+budgetSample.hour,weekly_used:+budgetSample.weekly,short_used:+budgetSample.short});if(dialogState!==current||serial!==policySerial)return;$('#policy-weekly-bar').innerHTML=policyBar(d.weekly,sampleDayLabel(budgetSample.day));$('#policy-short-bar').innerHTML=policyBar(d.short,sampleHourLabel(budgetSample.hour));$('#policy-results').textContent='';}catch(e){if(dialogState===current&&serial===policySerial&&$('#policy-results'))$('#policy-results').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
function loadAccountTester(){const el=$('#account-tester');if(!el)return;const s=cfg.subscriptions.find(s=>s.id===route.subscription);if(!s)return;el.innerHTML=testerHeading('Try this subscription’s windows')+`<div class="grid three">${select('Sample day · subscription timezone','sample.accountDay',accountSample.day,days.map((d,i)=>[i+1,d]))}${select('Sample hour','sample.accountHour',accountSample.hour,Array.from({length:24},(_,i)=>[i,String(i).padStart(2,'0')+':00']))}<div><label for="sample-account-used">Sample weekly used · ${accountSample.used}%</label><input id="sample-account-used" type="range" min="0" max="100" name="sample.accountUsed" value="${accountSample.used}"></div></div><div id="account-bar"></div><div id="account-results"></div>`;evaluateAccount();}
async function evaluateAccount(){const s=cfg.subscriptions.find(s=>s.id===route.subscription);if(!s||!$('#account-bar'))return;try{const d=await api('budget-preview',{subscription_id:s.id,now:sampleTime(+accountSample.day,+accountSample.hour,s.typical_reset.timezone||'America/Chicago'),sample:{weekly_used:+accountSample.used,availability:'ready'},max_band:'green',honor_overdrive:true});$('#account-bar').innerHTML=(d.display_note?'<p class="hint">'+esc(d.display_note)+'</p>':'')+powerbar(d,accountSample.used);$('#account-results').innerHTML=resultTable([{label:s.name,eligible:d.allowed,selected:d.allowed,reason:d.reason,selection_reason:d.reason}],true);}catch(e){if($('#account-results'))$('#account-results').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
function associationsView(){const byAuto=route.by!=='projects',atts=cfg.automation_attachments||[],q=k=>'/settings?'+new URLSearchParams({section:'associations',by:k,return:route.return}),targets=byAuto?cfg.automations:cfg.projects,sources=byAuto?cfg.projects:cfg.automations,tName=x=>byAuto?automationLabel(x):x.name,sName=x=>byAuto?x.name:automationLabel(x),key=l=>byAuto?l.definition_id:l.project_id,otherKey=l=>byAuto?l.project_id:l.definition_id,other=l=>byAuto?cfg.projects.find(p=>p.id===l.project_id):cfg.automations.find(a=>a.id===l.definition_id),noun=byAuto?'project':'automation';
return `<div class="heading"><h2>Project Associations ${info('associations','Project Associations')}</h2></div><nav class="segmented" aria-label="Arrange associations">${[['automations','By automation'],['projects','By project']].map(([k,t])=>`<a data-nav href="${esc(q(k))}" class="${route.by===k?'active':''}" ${route.by===k?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div id="assoc-feedback" class="assoc-feedback${assocFeedback?.error?' error':''}">${esc(assocFeedback?.text||'')}</div>${!cfg.projects.length||!cfg.automations.length?`<p class="empty">${cfg.projects.length?'Create a named automation first.':'Configure a project first.'}</p>`:`<div class="assoc"><section class="panel assoc-palette" data-drop="detach" aria-labelledby="assoc-source-title"><h3 id="assoc-source-title">${byAuto?'Projects':'Automations'}</h3><p class="hint">Drag ${byAuto?'a project onto an automation':'an automation onto a project'} to attach it.</p><ul class="assoc-sources">${sources.map(x=>`<li class="assoc-chip" draggable="true" data-drag="source" data-${byAuto?'project':'definition'}="${esc(x.id)}"><span class="grip" aria-hidden="true">⠿</span><span>${esc(sName(x))}</span><span class="meta">${atts.filter(l=>otherKey(l)===x.id).length} attached</span></li>`).join('')}</ul><p class="drop-label">Drop here to detach</p></section><div class="assoc-targets">${targets.map(t=>{const links=atts.filter(l=>key(l)===t.id),attached=new Set(links.map(otherKey)),avail=sources.filter(x=>!attached.has(x.id)),title=tName(t);return `<section class="panel assoc-card" data-drop="attach" data-target="${esc(t.id)}" aria-labelledby="assoc-${esc(t.id)}"><div class="toolbar"><h3 id="assoc-${esc(t.id)}" tabindex="-1">${esc(title)}</h3>${byAuto?button('edit-automation','Edit rules',`data-id="${esc(t.id)}" aria-label="Edit rules of ${esc(title)}"`,'link'):''}</div><p class="summary">${esc(byAuto?automationSummary(t):t.path)}</p><ul class="assoc-links">${links.map(l=>{const o=other(l),label=o?sName(o):'Unavailable '+noun,pair=byAuto?label+' with '+title:title+' with '+label;return `<li class="assoc-link ${l.enabled?'':'is-disabled'}" draggable="true" data-drag="attachment" data-attachment="${esc(l.id)}" data-project="${esc(l.project_id)}" data-definition="${esc(l.definition_id)}"><span class="grip" aria-hidden="true">⠿</span><span class="grow"><strong>${esc(label)}</strong><span class="meta"> · ${l.enabled?'Enabled':'Disabled · will not launch'} · priority ${esc(l.priority)}</span></span>${check('Enabled','association-enabled',l.enabled,`data-action="toggle-association" data-id="${esc(l.id)}" aria-label="Enable ${esc(pair)}"`)}${button('detach-association','Detach',`data-id="${esc(l.id)}" data-target="${esc(t.id)}" aria-label="Detach ${esc(pair)}"`,'link danger')}</li>`}).join('')||`<li class="empty">No ${noun}s attached.</li>`}</ul><p class="drop-label">Drop to attach to ${esc(title)}</p><div class="assoc-add">${select('Attach a '+noun,'assoc-add-'+t.id,'',[['',avail.length?'Choose a '+noun:'All '+noun+'s attached'],...avail.map(x=>[x.id,sName(x)])],avail.length?'':'disabled')}${button('attach-association','Attach',`data-target="${esc(t.id)}" aria-label="Attach the chosen ${noun} to ${esc(title)}" ${avail.length?'':'disabled'}`)}</div></section>`}).join('')}</div></div>`}`;}
function assocSay(text,error=false){assocFeedback={text,error};notify(text);}
async function assocCommit(apply,success,focus=''){try{for(let attempt=0;;attempt++){const c=copy(cfg),noop=apply(c);if(noop){assocSay(noop);break;}try{await commit(c,cfg.revision,success);assocFeedback={text:success,error:false};break;}catch(err){if(attempt||!/revision conflict/.test(err.message))throw err;cfg=await api('config');}}}catch(err){try{const c=await api('config');if(!cfg||c.revision>=cfg.revision)cfg=c;}catch{}assocSay('Not saved: '+err.message+'. The associations shown are the saved ones.',true);}pendingFocus=focus;render();}
async function attachAssociation(def,pid,focus){const a=cfg.automations.find(x=>x.id===def),p=cfg.projects.find(x=>x.id===pid);if(!a||!p)throw Error('That project or automation is no longer saved. Reload to see the saved associations.');const name=automationLabel(a);await assocCommit(c=>{if(!c.automations.some(x=>x.id===def)||!c.projects.some(x=>x.id===pid))throw Error(p.name+' or '+name+' was removed elsewhere');c.automation_attachments||=[];if(c.automation_attachments.some(l=>l.definition_id===def&&l.project_id===pid))return p.name+' already uses '+name+'. Nothing changed.';c.automation_attachments.push({id:id('attachment'),definition_id:def,project_id:pid,enabled:false,priority:10});return '';},'Attached '+p.name+' to '+name+'. It starts disabled; turn on Enabled when ready.',focus);}
async function detachAssociation(aid,focus){const l=(cfg.automation_attachments||[]).find(x=>x.id===aid);if(!l){assocSay('That association was already removed.');render();return;}const name=automationLabel(cfg.automations.find(x=>x.id===l.definition_id)),project=cfg.projects.find(x=>x.id===l.project_id)?.name||'The project';await assocCommit(c=>{const before=(c.automation_attachments||[]).length;c.automation_attachments=(c.automation_attachments||[]).filter(x=>x.id!==aid);return c.automation_attachments.length===before?'That association was already removed.':'';},'Detached '+project+' from '+name+'. Its rules and other projects are unchanged.',focus);}
function dropAccepts(zone){return !!(dragPayload&&zone)&&(zone.dataset.drop!=='detach'||dragPayload.kind==='attachment');}
document.addEventListener('dragstart',e=>{const el=e.target.closest?.('[data-drag]');if(!el)return;dragPayload={kind:el.dataset.drag,project:el.dataset.project||'',definition:el.dataset.definition||'',attachment:el.dataset.attachment||''};e.dataTransfer.effectAllowed='copyMove';e.dataTransfer.setData('text/plain',el.textContent.trim());document.body.classList.add('assoc-dragging',dragPayload.kind==='attachment'?'assoc-dragging-link':'assoc-dragging-source');el.classList.add('dragging');});
function endDrag(){dragPayload=null;document.body.classList.remove('assoc-dragging','assoc-dragging-link','assoc-dragging-source');document.querySelectorAll('.dragging,.drop-active').forEach(x=>x.classList.remove('dragging','drop-active'));}
document.addEventListener('dragend',endDrag);
document.addEventListener('dragover',e=>{const zone=e.target.closest?.('[data-drop]');if(!dropAccepts(zone))return;e.preventDefault();e.dataTransfer.dropEffect=zone.dataset.drop==='detach'?'move':'copy';document.querySelectorAll('.drop-active').forEach(x=>{if(x!==zone)x.classList.remove('drop-active')});zone.classList.add('drop-active');});
document.addEventListener('dragleave',e=>{const zone=e.target.closest?.('[data-drop]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drop-active');});
document.addEventListener('drop',async e=>{const zone=e.target.closest?.('[data-drop]');if(!dropAccepts(zone))return;e.preventDefault();const p=dragPayload;endDrag();try{if(zone.dataset.drop==='detach')await detachAssociation(p.attachment);else{const t=zone.dataset.target,byAuto=route.by!=='projects';await attachAssociation(byAuto?t:p.definition,byAuto?p.project:t);}}catch(err){assocSay(err.message,true);render();}});
async function removeDefinition(type,key,parent){const item=collection(cfg,type,parent)?.find(x=>x.id===key);if(!item)return;const refs=references(type,key);returnFocus=document.activeElement;returnSelector=focusSelector(returnFocus);dialogScroll=scrollY;dialogState={type:'delete',targetType:type,parent,item,revision:cfg.revision};$('#editor').innerHTML=`<div class="dialog-frame"><div class="dialog-head"><h2 id="dialog-title">Delete ${esc(labels[type])}</h2>${button('close-dialog','Close')}</div><div class="dialog-body"><p>Delete “${esc(item.name)}”?</p><p class="hint">Used by: ${esc(refs.join(', ')||'No saved references')}</p>${refs.length?'<p class="error">Reassign these references before deleting.</p>':''}<div id="dialog-error" role="alert"></div></div><div class="dialog-foot">${button('close-dialog','Cancel')}${button('confirm-delete',type==='time_windows'?'Delete time window':'Delete',refs.length?'disabled':'','link danger')}</div></div>`;if(!$('#editor').open){lockDialogPage();$('#editor').showModal();}}
async function confirmDelete(){const d=dialogState;try{if(references(d.targetType,d.item.id).length)throw Error('This definition still has saved references.');const next=copy(cfg),list=collection(next,d.targetType,d.parent),i=list.findIndex(x=>x.id===d.item.id);if(i<0)throw Error('Definition is unavailable.');if(d.targetType==='power_bands'&&d.item.id==='universal')throw Error('Universal is the default power band and remains editable.');list.splice(i,1);await commit(next,d.revision);if(d.targetType==='automations'){delete drafts[d.item.id];persistDrafts();if(draft?.id===d.item.id)draft=null;}closeDialog();if(d.targetType==='automations'&&route.automation===d.item.id)navigate(automationListURL(),true);}catch(e){$('#dialog-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
async function toggleConfig(update){const c=copy(cfg);update(c);try{await commit(c)}catch(e){await refresh(false);throw e}finally{render()}}
document.addEventListener('click',async e=>{const nav=e.target.closest('a[data-nav]');if(nav&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){const u=new URL(nav.href);if(u.pathname==='/plan'||u.pathname==='/archive'){saveView();return;}e.preventDefault();stashDraft();navigate(u.pathname+u.search);return;}const b=e.target.closest('[data-action]');if(!b||b.matches('input[type=checkbox]'))return;const action=b.dataset.action;try{switch(action){case 'sort-projects':projectSort(b.dataset.id);break;case 'filter-tag':filterProjectTag(b.dataset.id);break;case 'clear-tags':{const q=new URLSearchParams(location.search);q.delete('tag');navigate('/'+(q.size?'?'+q:''));break;}case 'retry':await refresh();break;case 'add-project':openEditor('projects');break;case 'register':{const x=newItem('projects');x.path=b.dataset.path;x.name=x.path.split('/').filter(Boolean).at(-1);openEditor('projects','','',false,x);break;}case 'add':openEditor(b.dataset.type,'',b.dataset.parent||'');break;case 'edit':case 'duplicate':if(dialogState?.type==='sequences'&&b.dataset.type==='presets'){capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);}openEditor(b.dataset.type,b.dataset.id,b.dataset.parent||'',action==='duplicate');break;case 'delete':if(dialogState?.type==='sequences'){capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);}await removeDefinition(b.dataset.type,b.dataset.id,b.dataset.parent||'');break;case 'confirm-delete':await confirmDelete();break;case 'close-dialog':closeDialog();break;case 'nested-preset':capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);openEditor('presets','',b.dataset.parent);break;case 'probe':{const out=await api('probe',{subscription_id:b.dataset.id});$('#readiness').textContent=Object.entries(out).map(([k,v])=>k+': '+v).join(' · ');break;}case 'usage-refresh':await api('usage',{subscription_id:b.dataset.id,expected_revision:cfg.revision,bind:true});await refresh();notify('Authentic usage refreshed.');break;case 'control':await api('control',{action:b.dataset.control,expected_revision:cfg.revision});await refresh();break;case 'tick':await api('tick',{expected_revision:cfg.revision});notify('Detached worker requested; admission checks remain authoritative.');await refresh();break;case 'attach-automation':{const definition=$('[name="attach-definition"]').value;if(!definition)throw Error('Choose a saved automation.');await toggleConfig(c=>{c.automation_attachments||=[];c.automation_attachments.push({id:id('attachment'),definition_id:definition,project_id:projectConfig().id,enabled:false,priority:10});});break;}case 'detach-automation':await toggleConfig(c=>c.automation_attachments=c.automation_attachments.filter(a=>a.id!==b.dataset.id));break;case 'duplicate-automation':{if(draft?.id===b.dataset.id)captureAutomation();const original=copy(draft?.id===b.dataset.id?draft.item:drafts[b.dataset.id]&&draftDirty(drafts[b.dataset.id])?drafts[b.dataset.id].item:cfg.automations.find(a=>a.id===b.dataset.id));if(!original)break;const item={...original,id:id('automation'),name:original.name+' copy',enabled:false};item.entries=(item.entries||[]).map(e=>({...e,id:id('entry')}));openAutomation('',item);break;}case 'add-automation':openAutomation();break;case 'edit-automation':openAutomation(b.dataset.id);break;case 'cancel-automation':{const d=draft,saved=cfg.automations.some(a=>a.id===d.id);delete drafts[d.id];persistDrafts();leaveEditor(saved?d.id:'');notify(saved?'Discarded unsaved changes. The saved rules are unchanged.':'Discarded the unsaved automation.');break;}case 'discard-draft':{const saved=cfg.automations.find(a=>a.id===b.dataset.id);delete drafts[b.dataset.id];persistDrafts();pendingFocus=saved?`[data-action="edit-automation"][data-id="${CSS.escape(saved.id)}"]`:'[data-action="add-automation"]';render();notify(saved?'Discarded unsaved changes to “'+saved.name+'”.':'Discarded the unsaved automation.');break;}case 'attach-association':{const t=b.dataset.target,sel=document.querySelector('[name="assoc-add-'+CSS.escape(t)+'"]'),other=sel?.value,byAuto=route.by!=='projects';if(!other)throw Error('Choose a '+(byAuto?'project':'automation')+' to attach.');await attachAssociation(byAuto?t:other,byAuto?other:t,'[name="assoc-add-'+CSS.escape(t)+'"]');break;}case 'detach-association':await detachAssociation(b.dataset.id,'[name="assoc-add-'+CSS.escape(b.dataset.target||'')+'"]');break;case 'automation-mode':captureAutomation();draft.item.mode=b.dataset.mode;if(draft.item.mode==='overdrive'){draft.item.honor_engine_overdrive=true;draft.item.only_during_overdrive=true;draft.item.window_id='';}else{draft.item.honor_engine_overdrive=false;draft.item.only_during_overdrive=false;draft.item.window_id=draft.item.mode==='scheduled'?draft.window?.id||'':'';}renderAutomation();break;case 'entry-add':captureAutomation();if(fullSequences().length)draft.item.entries.push({id:id('entry'),sequence_id:fullSequences()[0].id,max_band:'green'});renderAutomation();break;case 'entry-up':case 'entry-down':case 'entry-remove':{captureAutomation();const i=+b.dataset.index,es=draft.item.entries;if(action==='entry-remove')es.splice(i,1);else{const j=i+(action==='entry-up'?-1:1);if(j>=0&&j<es.length)[es[i],es[j]]=[es[j],es[i]];}renderAutomation();break;}case 'new-auto-window':captureAutomation();draft.window={...newItem('time_windows'),name:draft.item.name+' time window'};draft.item.window_id=draft.window.id;renderAutomation();break;case 'delete-automation':await removeDefinition('automations',draft.item.id,'');break;case 'refresh-activity':await refreshActivity();break;}}catch(err){notify(err.message);}});
document.addEventListener('submit',e=>{if(e.target.id==='definition-form')saveDefinition(e);if(e.target.id==='automation-form')saveAutomation(e)});
$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
$('#editor').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...$('#editor').querySelectorAll('button:not(:disabled),input,select,textarea,a[href],summary')].filter(x=>x.getClientRects().length);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!dialogState||dialogState.type!=='subscriptions')return;const d=dialogState;try{if(['add-argument','remove-argument'].includes(action)){capture($('#definition-form'),d.item);const b=e.target.closest('[data-action]'),key=b.dataset.name;d.item[key]||=[];if(action==='add-argument')d.item[key].push('');else d.item[key].splice(+b.dataset.index,1);showEditor();return;}if(action==='edit-program'){capture($('#definition-form'),d.item);d.editPath=true;showEditor();return;}if(action==='refresh-editor-usage'){capture($('#definition-form'),d.item);notify('Refresh uses the saved subscription and can bind its authenticated account.');await api('usage',{subscription_id:d.item.id,expected_revision:cfg.revision,bind:true});await refresh(false);d.item.account_id=cfg.subscriptions.find(s=>s.id===d.item.id)?.account_id||'';d.item.pool_id=cfg.subscriptions.find(s=>s.id===d.item.id)?.pool_id||'';d.revision=cfg.revision;showEditor();return;}if(action==='detect-program'||action==='verify-program'){capture($('#definition-form'),d.item);$('#program-status').textContent='Checking installed program…';const out=await api(action==='detect-program'?'detect':'probe',{subscription:d.item});if(dialogState!==d)return;d.probe=out;showEditor();if(action==='verify-program'){const out=await api('preview',{subscription:d.item,sequence:d.item.sequences?.[0]||{}});if(dialogState===d&&$('#subscription-command'))$('#subscription-command').textContent=out.command;}}}catch(err){if($('#program-status'))$('#program-status').textContent=err.message;}});
let debounce;
document.addEventListener('input',e=>{if(draft&&e.target.name==='name'&&e.target.closest('#automation-form')){captureAutomation();const n=$('#draft-note');if(n)n.innerHTML=draftNote();}if(dialogState?.conversion&&/^(hours_before_reset|start_mode|end_mode|end_day|end_time|recurrence\.)/.test(e.target.name||'')){dialogState.conversion=null;$('#conversion-info')?.remove();}if(e.target.name?.startsWith('sample.'))sampleChanged(e.target);else if(dialogState?.type==='sequences'){clearTimeout(debounce);debounce=setTimeout(previewCommand,200);}else if(dialogState?.type==='power_bands'){clearTimeout(debounce);debounce=setTimeout(evaluateBudget,200);}});
document.addEventListener('change',async e=>{const x=e.target;if(x.name?.startsWith('sample.')){sampleChanged(x);return;}try{switch(x.dataset.action){case 'toggle-subscription':await toggleConfig(c=>c.subscriptions.find(s=>s.id===x.dataset.id).enabled=x.checked);return;case 'toggle-project':await toggleConfig(c=>c.projects.find(p=>p.id===x.dataset.id).enabled=x.checked);return;case 'toggle-automation':await toggleConfig(c=>c.automation_attachments.find(a=>a.id===x.dataset.id).enabled=x.checked);return;case 'toggle-association':{const on=x.checked,sel='[data-action="toggle-association"][data-id="'+CSS.escape(x.dataset.id)+'"]',label=x.getAttribute('aria-label').replace(/^Enable /,'');await assocCommit(c=>{const l=(c.automation_attachments||[]).find(a=>a.id===x.dataset.id);if(!l)throw Error('That association was removed elsewhere');if(l.enabled===on)return label+' is already '+(on?'enabled':'disabled')+'.';l.enabled=on;return '';},(on?'Enabled ':'Disabled ')+label+'.',sel);return;}case 'attachment-priority':await toggleConfig(c=>c.automation_attachments.find(a=>a.id===x.dataset.id).priority=+x.value);return;case 'toggle-overdrive':await toggleConfig(c=>c.subscriptions.find(s=>s.id===x.dataset.id).overdrive_enabled=x.checked);return;case 'toggle-window':await toggleConfig(c=>c.subscriptions.find(s=>s.id===x.dataset.parent).overdrive_windows.find(w=>w.id===x.dataset.id).enabled=x.checked);return;}
if(dialogState&&x.closest('#definition-form')){const d=dialogState,priorMode=d.item.start_mode,priorTool=d.item.adapter;capture($('#definition-form'),d.item);if(d.type==='subscriptions'&&x.name==='adapter'){const defaults={codex:'codex',claude:'claude',generic:'',custom:''};const customPath=d.item.executable&&d.item.executable!==defaults[priorTool];if(!customPath)d.item.executable=defaults[x.value]||'';const defaultArgs=!d.item.args?.length||JSON.stringify(d.item.args)==='["{prompt}"]';if(defaultArgs)d.item.args=x.value==='generic'?['{prompt}']:[];d.toolNotice=customPath||!defaultArgs||(d.item.sequences||[]).some(q=>q.model||q.reasoning||q.preset_id||q.args?.length)||d.item.usage_command?.length?'Your custom program or arguments are preserved. Verify compatibility with the selected AI tool before saving. Review model and permission overrides in Named Launch Sequences.':'';d.editPath=!!customPath;d.item.account_id='';d.item.pool_id='';d.probe=null;showEditor();return;}if(d.type==='overdrive_windows'&&!d.isNew&&x.name==='start_mode'&&priorMode==='weekly'&&x.value==='reset_relative'){const saved=collection(cfg,d.type,d.parent).find(w=>w.id===d.item.id);if(JSON.stringify(saved?.recurrence)!==JSON.stringify(d.item.recurrence)||saved?.end_mode!==d.item.end_mode||saved?.end_day!==d.item.end_day||saved?.end_time!==d.item.end_time){d.item.start_mode=priorMode;showEditor();$('#dialog-error').textContent='Save timing changes before converting this window.';return;}try{const converted=await api('overdrive-conversion',{subscription_id:d.parent,window_id:d.item.id});if(dialogState!==d)return;if(converted.revision!==d.revision)throw Error('Configuration changed. Reopen the window before converting.');d.item={...converted.window,name:d.item.name,enabled:d.item.enabled,target_used_percent:d.item.target_used_percent};d.conversion=converted;showEditor();}catch(err){d.item.start_mode=priorMode;showEditor();$('#dialog-error').textContent=err.message;}return;}if(x.name==='template'&&x.value){const t=copy(cfg.subscriptions.find(s=>s.id===x.value)),mapping={};t.id=dialogState.item.id;t.name=t.name+' account';t.enabled=false;t.account_id='';t.pool_id='';for(const key of ['sequences','presets','overdrive_windows'])for(const child of t[key]||[]){mapping[child.id]=id(key);child.id=mapping[child.id];}for(const q of t.sequences||[])if(mapping[q.preset_id])q.preset_id=mapping[q.preset_id];dialogState.item=t;showEditor();}else if(['start_mode','end_mode','preset_id','recurrence.all_day'].includes(x.name))showEditor();return;}
if(draft&&x.closest('#automation-form')){captureAutomation();if(x.dataset.windowPicker!==undefined){draft.window=copy(cfg.time_windows.find(w=>w.id===x.value));renderAutomation();}else if(['on_window_end','start_mode','end_mode'].includes(x.name))renderAutomation();else renderAutomationTester();}}catch(err){notify(err.message);}});
function sampleChanged(x){const n=x.name,v=x.type==='checkbox'?x.checked:x.value;if(n.startsWith('sample.account')){if(n==='sample.accountDay')accountSample.day=+v;if(n==='sample.accountHour')accountSample.hour=+v;if(n==='sample.accountUsed'){accountSample.used=+v;x.previousElementSibling.textContent='Sample weekly used · '+v+'%';}evaluateAccount();return;}if(n.startsWith('sample.budget')||n==='sample.subscription'){if(n==='sample.subscription')budgetSample.subscription=v;if(n==='sample.budgetDay')budgetSample.day=+v;if(n==='sample.budgetWeekly')budgetSample.weekly=+v;if(n==='sample.budgetShort')budgetSample.short=+v;if(n==='sample.budgetHour')budgetSample.hour=+v;if(x.type==='range')x.previousElementSibling.textContent=n==='sample.budgetDay'?'Sample day · '+sampleDayLabel(v):n==='sample.budgetHour'?'Elapsed · '+sampleHourLabel(v):(n==='sample.budgetShort'?'Sample 5-hour used · ':'Weekly used · ')+v+'%';sessionStorage.setItem('conductor-budget-sample',JSON.stringify(budgetSample));evaluateBudget();return;}if(!draft)return;const ss=draft.sample;if(n==='sample.window'){ss.window=v;renderAutomationTester();return;}if(n==='sample.used'){ss.used=+v;x.previousElementSibling.textContent='Sample weekly used · '+v+'%';}if(n==='sample.day')ss.day=+v;if(n==='sample.hour')ss.hour=+v;if(n==='sample.band')ss.band=v;if(n==='sample.overdrive')ss.overdrive=v;persistDrafts();evaluateAutomation();}
try{drafts=JSON.parse(sessionStorage.getItem('conductor-drafts')||'{}')||{};const legacy=JSON.parse(sessionStorage.getItem('conductor-draft')||'null');if(legacy?.item?.id&&!drafts[legacy.item.id]){const {projectPath,...rest}=legacy;drafts[legacy.item.id]={...rest,id:legacy.item.id,sample:{band:'green',day:1,hour:12,used:38,overdrive:false,window:''}};}}catch{drafts={}}
